#include "../src/services/geometry/print/McutMeshBooleanService.h"
#include "../src/services/geometry/print/PrintMeshAnalysis.h"
#include <QCoreApplication>
#include <QTextStream>
using namespace PrintGeometry;
namespace {bool check(bool v,const QString&m){if(!v)QTextStream(stderr)<<"FAIL: "<<m<<Qt::endl;return v;}PrintMesh box(double x0,double y0,double z0,double x1,double y1,double z1){PrintMesh m;m.vertices={{x0,y0,z0},{x1,y0,z0},{x1,y1,z0},{x0,y1,z0},{x0,y0,z1},{x1,y0,z1},{x1,y1,z1},{x0,y1,z1}};m.faces={{0,2,1},{0,3,2},{4,5,6},{4,6,7},{0,1,5},{0,5,4},{3,7,6},{3,6,2},{0,4,7},{0,7,3},{1,2,6},{1,6,5}};return m;}}
int main(int argc,char**argv){QCoreApplication app(argc,argv);bool ok=check(McutMeshBooleanService::available(),"MCUT available");McutMeshBooleanService service;auto source=box(0,0,0,2,2,2),add=box(1,0,0,3,2,2);auto result=service.unite(source,add);ok&=check(result.ok(),QString::fromStdString(result.message));if(result.ok()){ok&=check(validateBooleanOperand(result.resultAnalysis).ok(),"union independently valid");ok&=check(std::abs(result.resultAnalysis.absoluteVolume-12.0)<0.01,"union volume");auto again=service.unite(source,add);ok&=check(again.ok()&&again.resultAnalysis.triangles==result.resultAnalysis.triangles,"deterministic union metrics");}auto open=source;open.faces.pop_back();ok&=check(service.unite(open,add).error==MeshBooleanError::InvalidSource,"open operand rejected before MCUT");PrintMesh multi=source;auto offset=std::uint32_t(multi.vertices.size());auto far=box(10,0,0,11,1,1);multi.vertices.insert(multi.vertices.end(),far.vertices.begin(),far.vertices.end());for(auto f:far.faces){for(auto&i:f)i+=offset;multi.faces.push_back(f);}ok&=check(service.unite(multi,add).error==MeshBooleanError::InvalidSource,"multi-component operand rejected");return ok?0:1;}
